#!/usr/bin/env python3
# Compatibility wrapper: the primary publication figures are generated by analyze_geometry_opportunity.py.
import argparse, subprocess, sys
ap=argparse.ArgumentParser(); ap.add_argument('--ledger',required=True); ap.add_argument('--out',required=True); a=ap.parse_args()
subprocess.check_call([sys.executable,'scripts/analyze_geometry_opportunity.py','--ledger',a.ledger,'--out',a.out])
